pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.warp(100);
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1);
        vm.warp(100);
        vm.warp(101);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        c = new Roulette();
        vm.warp(100);
        vm.deal(address(this), 10 ether);
        address(c).call{value: 10 ether}("");
        assertTrue(c.pastBlockTime() == 100);
    }
}
